public class DailyAssignment_Dowhile_evenOdd {
	
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int num=1;
		do {
			
			if(num%2==0)
			{
				num++;
				continue;
			}
			else if (num>=15) {
				break;
			}
			
			System.out.println("odd number "+ num);
			num++;
			
		}while(num<20);
		{
			
			
		
			
	}
	
	}
	

}
	



	

